import { load } from "/vendor/zstd/wasm-zoo-cli.mjs";
const cli = await load({baseUrl:"/vendor/zstd/"});
try {
  const compressed = await cli.exec(["-q","-f","-5","-o","/out.zst","/in.txt"], {
    files: [{name:"/in.txt",data:new TextEncoder().encode("hello")}], outputs:["/out.zst"]
  });
  console.log(compressed.files[0].data);
} finally { cli.dispose(); }

docs.example:
import { load } from "@wasm-zoo/zstd";

const zstd = await load();
try {
  const original = new TextEncoder().encode("WASM Zoo ".repeat(100));
  const packed = await zstd.exec(["-q", "-f", "-5", "-o", "/result.zst", "/input.txt"], {
    files: [{ name: "/input.txt", data: original }],
    outputs: ["/result.zst"]
  });
  console.log(packed.files[0].data);
} finally {
  zstd.dispose();
}
